import React from 'react';

function Home() {
  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center p-6">
      <div className="text-center">
        {/* Title */}
        <h1 className="text-5xl font-bold text-white mb-3">Inventory Management</h1>
        <p className="text-xl text-white/90 mb-12">Manage your items efficiently</p>
        
        {/* Buttons */}
        <div className="flex flex-col sm:flex-row gap-6 justify-center">
          <button
            onClick={() => (window.location.href = '/additem')}
            className="bg-white hover:bg-gray-100 text-purple-600 font-bold text-lg px-10 py-5 rounded-xl shadow-lg hover:shadow-xl transition-all duration-200 flex items-center justify-center gap-3"
          >
            <span className="text-3xl">➕</span>
            <span>Add Item</span>
          </button>
          
          <button
            onClick={() => (window.location.href = '/allitems')}
            className="bg-white hover:bg-gray-100 text-purple-600 font-bold text-lg px-10 py-5 rounded-xl shadow-lg hover:shadow-xl transition-all duration-200 flex items-center justify-center gap-3"
          >
            <span className="text-3xl">📋</span>
            <span>All Items</span>
          </button>
        </div>
      </div>
    </div>
  );
}

export default Home;
